class Solution {
    static ArrayList<Integer> findUnion(int[] a, int[] b) {
        ArrayList<Integer> union = new ArrayList<>();

        int i = 0;
        int j = 0;

        while (i < a.length && j < b.length) {
            int value;

            if (a[i] < b[j]) {
                value = a[i++];
            } else if (b[j] < a[i]) {
                value = b[j++];
            } else {
                value = a[i];
                i++;
                j++;
            }

            if (union.isEmpty() || union.get(union.size() - 1) != value) {
                union.add(value);
            }
        }

        while (i < a.length) {
            if (union.isEmpty() || union.get(union.size() - 1) != a[i]) {
                union.add(a[i]);
            }
            i++;
        }

        while (j < b.length) {
            if (union.isEmpty() || union.get(union.size() - 1) != b[j]) {
                union.add(b[j]);
            }
            j++;
        }

        return union;
    }
}

