class Solution {
    static int subarraysWithXorK(int[] arr, int k) {
        HashMap<Integer, Integer> map = new HashMap<>();
        map.put(0, 1);

        int xor = 0;
        int count = 0;

        for (int x : arr) {
            xor ^= x;

            int need = xor ^ k;

            count += map.getOrDefault(need, 0);

            map.put(xor, map.getOrDefault(xor, 0) + 1);
        }

        return count;
    }
}

