class Solution {
    static int nthRoot(int n, int m) {
        int low = 1;
        int high = m;

        while (low <= high) {
            int mid = low + (high - low) / 2;

            long value = power(mid, n, m);

            if (value == m) {
                return mid;
            } else if (value < m) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        return -1;
    }

    static long power(int base, int exp, int limit) {
        long result = 1;

        for (int i = 0; i < exp; i++) {
            result *= base;

            if (result > limit) {
                return limit + 1L;
            }
        }

        return result;
    }
}

