        List<int[]> result = new ArrayList<>();

        if (head == null) return result;

        DLLNode left = head;
        DLLNode right = head;

        while (right.next != null) {
            right = right.next;
        }

        while (left != right && right.next != left) {
            int sum = left.data + right.data;

            if (sum == target) {
                result.add(new int[]{left.data, right.data});
                left = left.next;
                right = right.prev;
            } else if (sum < target) {
                left = left.next;
            } else {
                right = right.prev;
            }
        }

        return result;
    }
