class Solution {
    static List<String> findPath(int[][] maze) {
        List<String> result = new ArrayList<>();

        int n = maze.length;

        if (maze[0][0] == 0) return result;

        boolean[][] visited = new boolean[n][n];

        solve(0, 0, maze, visited, "", result);

        return result;
    }

    private static void solve(
        int r,
        int c,
        int[][] maze,
        boolean[][] visited,
        String path,
        List<String> result
    ) {
        int n = maze.length;

        if (r == n - 1 && c == n - 1) {
            result.add(path);
            return;
        }

        visited[r][c] = true;

        int[] dr = {1, 0, 0, -1};
        int[] dc = {0, -1, 1, 0};
        char[] move = {'D', 'L', 'R', 'U'};

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];

            if (nr >= 0 && nc >= 0 &&
                nr < n && nc < n &&
                maze[nr][nc] == 1 &&
                !visited[nr][nc]) {

                solve(nr, nc, maze, visited,
                      path + move[i], result);
            }
        }

        visited[r][c] = false;
    }
}

