class Solution {
    public boolean wordBreak(String s, List<String> wordDict) {
        HashSet<String> set = new HashSet<>(wordDict);
        Boolean[] memo = new Boolean[s.length()];

        return solve(0, s, set, memo);
    }

    private boolean solve(
        int start,
        String s,
        HashSet<String> set,
        Boolean[] memo
    ) {
        if (start == s.length()) return true;

        if (memo[start] != null) return memo[start];

        for (int end = start + 1; end <= s.length(); end++) {
            String word = s.substring(start, end);

            if (set.contains(word) &&
                solve(end, s, set, memo)) {
                return memo[start] = true;
            }
        }

        return memo[start] = false;
    }
}

class Solution {
    static boolean graphColoring(int[][] graph, int m) {
        int[] color = new int[graph.length];

        return solve(0, graph, m, color);
    }

    private static boolean solve(
        int node,
        int[][] graph,
        int m,
        int[] color
    ) {
        if (node == graph.length) return true;

        for (int c = 1; c <= m; c++) {
            if (isSafe(node, c, graph, color)) {
                color[node] = c;

                if (solve(node + 1, graph, m, color)) {
                    return true;
                }

                color[node] = 0;
            }
        }

        return false;
    }

    private static boolean isSafe(
        int node,
        int c,
        int[][] graph,
        int[] color
    ) {
        for (int i = 0; i < graph.length; i++) {
            if (graph[node][i] == 1 && color[i] == c) {
                return false;
            }
        }

        return true;
    }
}

class Solution {
    public void solveSudoku(char[][] board) {
        solve(board);
    }

    private boolean solve(char[][] board) {
        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                if (board[r][c] == '.') {
                    for (char ch = '1'; ch <= '9'; ch++) {
                        if (isValid(board, r, c, ch)) {
                            board[r][c] = ch;

                            if (solve(board)) return true;

                            board[r][c] = '.';
                        }
                    }

                    return false;
                }
            }
        }

        return true;
    }

    private boolean isValid(
        char[][] board,
        int row,
        int col,
        char ch
    ) {
        for (int i = 0; i < 9; i++) {
            if (board[row][i] == ch) return false;
            if (board[i][col] == ch) return false;

            int r = 3 * (row / 3) + i / 3;
            int c = 3 * (col / 3) + i % 3;

            if (board[r][c] == ch) return false;
        }

        return true;
    }
}

