class StockSpanner {
    Stack<int[]> stack = new Stack<>();

    public int next(int price) {
        int span = 1;

        while (!stack.isEmpty() && stack.peek()[0] <= price) {
            span += stack.pop()[1];
        }

        stack.push(new int[]{price, span});

        return span;
    }
}

class Solution {
    static int celebrity(int[][] matrix) {
        int n = matrix.length;
        int candidate = 0;

        for (int i = 1; i < n; i++) {
            if (matrix[candidate][i] == 1) {
                candidate = i;
            }
        }

        for (int i = 0; i < n; i++) {
            if (i == candidate) continue;

            if (matrix[candidate][i] == 1 ||
                matrix[i][candidate] == 0) {
                return -1;
            }
        }

        return candidate;
    }
}

import java.util.*;

class LRUCache {
    class Node {
        int key;
        int value;
        Node prev;
        Node next;

        Node(int key, int value) {
            this.key = key;
            this.value = value;
        }
    }

    int capacity;
    HashMap<Integer, Node> map = new HashMap<>();
    Node head = new Node(0, 0);
    Node tail = new Node(0, 0);

    public LRUCache(int capacity) {
        this.capacity = capacity;
        head.next = tail;
        tail.prev = head;
    }

    public int get(int key) {
        if (!map.containsKey(key)) return -1;

        Node node = map.get(key);
        remove(node);
        insertFront(node);

        return node.value;
    }

    public void put(int key, int value) {
        if (map.containsKey(key)) {
            remove(map.get(key));
        }

        Node node = new Node(key, value);
        insertFront(node);
        map.put(key, node);

        if (map.size() > capacity) {
            Node lru = tail.prev;
            remove(lru);
            map.remove(lru.key);
        }
    }

    private void remove(Node node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    private void insertFront(Node node) {
        node.next = head.next;
        node.prev = head;

        head.next.prev = node;
        head.next = node;
    }
}

import java.util.*;

class LFUCache {
    int capacity;
    int minFreq = 0;

    HashMap<Integer, Integer> values = new HashMap<>();
    HashMap<Integer, Integer> freq = new HashMap<>();
    HashMap<Integer, LinkedHashSet<Integer>> groups = new HashMap<>();

    public LFUCache(int capacity) {
        this.capacity = capacity;
    }

    public int get(int key) {
        if (!values.containsKey(key)) return -1;

        touch(key);
        return values.get(key);
    }

    public void put(int key, int value) {
        if (capacity == 0) return;

        if (values.containsKey(key)) {
            values.put(key, value);
            touch(key);
            return;
        }

        if (values.size() == capacity) {
            LinkedHashSet<Integer> set = groups.get(minFreq);
            int removeKey = set.iterator().next();

            set.remove(removeKey);
            values.remove(removeKey);
            freq.remove(removeKey);
        }

        values.put(key, value);
        freq.put(key, 1);

        groups.computeIfAbsent(1, x -> new LinkedHashSet<>()).add(key);

        minFreq = 1;
    }

    private void touch(int key) {
        int f = freq.get(key);

        groups.get(f).remove(key);

        if (groups.get(f).isEmpty() && minFreq == f) {
            minFreq++;
        }

        freq.put(key, f + 1);

        groups.computeIfAbsent(f + 1, x -> new LinkedHashSet<>()).add(key);
    }
}

import java.util.*;

class Solution {
    public int lengthOfLongestSubstring(String s) {
        int[] last = new int[256];
        Arrays.fill(last, -1);

        int left = 0;
        int maxLen = 0;

        for (int right = 0; right < s.length(); right++) {
            char ch = s.charAt(right);

            if (last[ch] >= left) {
                left = last[ch] + 1;
            }

            last[ch] = right;

            maxLen = Math.max(maxLen, right - left + 1);
        }

        return maxLen;
    }
}

class Solution {
    public int longestOnes(int[] nums, int k) {
        int left = 0;
        int zeros = 0;
        int maxLen = 0;

        for (int right = 0; right < nums.length; right++) {
            if (nums[right] == 0) {
                zeros++;
            }

            while (zeros > k) {
                if (nums[left] == 0) {
                    zeros--;
                }
                left++;
            }

            maxLen = Math.max(maxLen, right - left + 1);
        }

        return maxLen;
    }
}

