class Solution {
    public int totalFruit(int[] fruits) {
        HashMap<Integer, Integer> map = new HashMap<>();

        int left = 0;
        int maxLen = 0;

        for (int right = 0; right < fruits.length; right++) {
            map.put(
                fruits[right],
                map.getOrDefault(fruits[right], 0) + 1
            );

            while (map.size() > 2) {
                int value = fruits[left];

                map.put(value, map.get(value) - 1);

                if (map.get(value) == 0) {
                    map.remove(value);
                }

                left++;
            }

            maxLen = Math.max(maxLen, right - left + 1);
        }

        return maxLen;
    }
}

class Solution {
    public int characterReplacement(String s, int k) {
        int[] freq = new int[26];

        int left = 0;
        int maxFreq = 0;
        int maxLen = 0;

        for (int right = 0; right < s.length(); right++) {
            int index = s.charAt(right) - 'A';

            freq[index]++;
            maxFreq = Math.max(maxFreq, freq[index]);

            while ((right - left + 1) - maxFreq > k) {
                freq[s.charAt(left) - 'A']--;
                left++;
            }

            maxLen = Math.max(maxLen, right - left + 1);
        }

        return maxLen;
    }
}

class Solution {
    public int numSubarraysWithSum(int[] nums, int goal) {
        return atMost(nums, goal) - atMost(nums, goal - 1);
    }

    private int atMost(int[] nums, int goal) {
        if (goal < 0) return 0;

        int left = 0;
        int sum = 0;
        int count = 0;

        for (int right = 0; right < nums.length; right++) {
            sum += nums[right];

            while (sum > goal) {
                sum -= nums[left++];
            }

            count += right - left + 1;
        }

        return count;
    }
}

class Solution {
    public int numberOfSubarrays(int[] nums, int k) {
        return atMost(nums, k) - atMost(nums, k - 1);
    }

    private int atMost(int[] nums, int k) {
        int left = 0;
        int odd = 0;
        int count = 0;

        for (int right = 0; right < nums.length; right++) {
            if ((nums[right] & 1) == 1) {
                odd++;
            }

            while (odd > k) {
                if ((nums[left] & 1) == 1) {
                    odd--;
                }

                left++;
            }

            count += right - left + 1;
        }

        return count;
    }
}

class Solution {
    public int numberOfSubstrings(String s) {
        int[] last = {-1, -1, -1};
        int count = 0;

        for (int i = 0; i < s.length(); i++) {
            last[s.charAt(i) - 'a'] = i;

            int minIndex = Math.min(
                last[0],
                Math.min(last[1], last[2])
            );

            if (minIndex != -1) {
                count += minIndex + 1;
            }
        }

        return count;
    }
}

class Solution {
    public int maxScore(int[] cardPoints, int k) {
        int total = 0;

        for (int x : cardPoints) {
            total += x;
        }

        int window = cardPoints.length - k;

        if (window == 0) return total;

        int current = 0;

        for (int i = 0; i < window; i++) {
            current += cardPoints[i];
        }

        int minWindow = current;

        for (int i = window; i < cardPoints.length; i++) {
            current += cardPoints[i];
            current -= cardPoints[i - window];

            minWindow = Math.min(minWindow, current);
        }

        return total - minWindow;
    }
}

